/* ---- scroll-reveal: fade + rise the intro and actions into view ---- */
(function(){
  document.body.classList.add('anim-ready');   /* gate hidden state on JS being present */
  var els = document.querySelectorAll('.anim');
  if (!('IntersectionObserver' in window)){
    els.forEach(function(el){ el.classList.add('in'); });
    return;
  }
  var io = new IntersectionObserver(function(entries){
    entries.forEach(function(e){
      if (e.isIntersecting){ e.target.classList.add('in'); io.unobserve(e.target); }
    });
  }, { threshold:0.18, rootMargin:'0px 0px -8% 0px' });
  els.forEach(function(el){ io.observe(el); });
})();


/* ---- TWO-TRACK STAGE ---------------------------------------------------
   The transition from the reference recording, in four beats:
     1. is-morphing  the centre ring squeezes into a capsule        (170ms)
     2. is-filling   a filled disc in the INCOMING colour appears   (150ms)
     3. is-expanding that disc scales up until it covers the stage  (780ms)
                     and the slide/emblem/colour swap happens under it
     4. is-clearing  the disc fades out, revealing the new track
   The blob scale is computed from the viewport diagonal, so the disc always
   covers the stage no matter the window size.
   The existing .ptab buttons drive the same routine, so the tabs below and
   the stage never disagree about which track is showing. ---------------- */
(function(){
  var stage = document.getElementById('trackStage');
  if (!stage) return;
  var blob   = document.getElementById('tsBlob');
  var morph  = document.getElementById('tsMorph');
  var slides = stage.querySelectorAll('.ts-slide');
  var arts   = stage.querySelectorAll('.ts-art-wrap');
  var rail   = stage.querySelectorAll('.ts-rail-item');
  var nextEl = document.getElementById('tsNextName');
  var tabs   = document.querySelectorAll('.ptab');
  var panels = document.querySelectorAll('.ppanel');

  var COLOURS = { ai:'#f46718', cy:'#12857c' };
  var ORDER   = ['ai','cy'];
  var busy = false;
  var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  function paint(track){
    stage.setAttribute('data-active', track);
    stage.style.setProperty('--tc', COLOURS[track]);
    slides.forEach(function(s){ s.classList.toggle('is-on', s.getAttribute('data-track') === track); });
    arts.forEach(function(a){ a.classList.toggle('is-on', a.getAttribute('data-track') === track); });
    rail.forEach(function(r){
      var on = r.getAttribute('data-go') === track;
      r.classList.toggle('is-on', on);
      r.setAttribute('aria-current', on ? 'true' : 'false');
    });
    // the control names where it goes, so the other track is never a mystery
    if (nextEl) nextEl.textContent = track === 'ai' ? 'Cyber Security' : 'AI Track';
    tabs.forEach(function(t){
      var on = t.getAttribute('data-track') === track;
      t.classList.toggle('is-on', on);
      t.setAttribute('aria-selected', on ? 'true' : 'false');
    });
    panels.forEach(function(p){ p.classList.toggle('is-on', p.getAttribute('data-track') === track); });
  }

  function go(track){
    if (busy) return;
    if (stage.getAttribute('data-active') === track) return;
    if (reduce){ paint(track); return; }
    busy = true;

    /* the disc has to cover the whole stage from its centre */
    var r = stage.getBoundingClientRect();
    var scale = Math.ceil(Math.hypot(r.width, r.height) / 78) + 2;
    stage.style.setProperty('--blob-scale', scale);
    stage.style.setProperty('--next-tc', COLOURS[track]);

    stage.classList.add('is-morphing');
    setTimeout(function(){
      stage.classList.add('is-filling');
      setTimeout(function(){
        stage.classList.remove('is-morphing');
        stage.classList.add('is-expanding');
        /* swap underneath while the disc is mid-flight */
        setTimeout(function(){ paint(track); }, 300);
        setTimeout(function(){
          stage.classList.add('is-clearing');
          setTimeout(function(){
            stage.classList.remove('is-filling','is-expanding','is-clearing');
            busy = false;
          }, 440);
        }, 700);
      }, 150);
    }, 170);
  }

  function other(){
    var i = ORDER.indexOf(stage.getAttribute('data-active'));
    return ORDER[(i + 1) % ORDER.length];
  }

  if (morph) morph.addEventListener('click', function(){ go(other()); });
  rail.forEach(function(r){
    r.addEventListener('click', function(){ go(r.getAttribute('data-go')); });
  });
  tabs.forEach(function(t){
    t.addEventListener('click', function(){ go(t.getAttribute('data-track')); });
  });

  paint(stage.getAttribute('data-active') || 'ai');
})();

/* logo colour adapts to the section behind it (white on dark, orange on light) */
(function(){
  var logo = document.querySelector('.site-logo');
  if (!logo || !('IntersectionObserver' in window)) return;
  var darks = [];
  ['.hero', '.cta-section', '.footer'].forEach(function(sel){
    document.querySelectorAll(sel).forEach(function(el){ darks.push(el); });
  });
  if (!darks.length) return;
  var active = new Set();
  var io = new IntersectionObserver(function(entries){
    entries.forEach(function(e){ if (e.isIntersecting) active.add(e.target); else active.delete(e.target); });
    logo.classList.toggle('on-dark', active.size > 0);
  }, { rootMargin:'-44px 0px -92% 0px', threshold:0 });
  darks.forEach(function(el){ io.observe(el); });
})();

